    private static NamespaceResolver nsr;
    private NodePointer parent;
    private QName name;
    private List<Attribute> attributes;
    private JDOMAttributeIterator iterator;

    @Rule
    public ExpectedException expectedEx = ExpectedException.none();

    @BeforeClass
    public static void setUpClass(){
        nsr = mock(NamespaceResolver.class);
    }

    @Before
    public void setUp(){
        Element element = new Element("root");
        name = new QName("*", "test");
        parent = new NodePointer(element, nsr);
        attributes = new ArrayList<>();
        Attribute attribute1 = new Attribute("test1", "value1", Namespace.NO_NAMESPACE);
        Attribute attribute2 = new Attribute("test2", "value2", Namespace.NO_NAMESPACE);
        attributes.add(attribute1);
        attributes.add(attribute2);
    }

    @Test
    public void testSetPositionWithNullAttributes(){
        parent.setNode(null);
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertFalse(iterator.setPosition(1));
    }

    @Test
    public void testSetPositionOutOfBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertFalse(iterator.setPosition(3));
    }

    @Test
    public void testSetPositionInBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertTrue(iterator.setPosition(1));
        Assert.assertEquals(attribute1, iterator.getNodePointer().get());
    }

    @Test
    public void testGetNodePointerWithNullAttributes(){
        parent.setNode(null);
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertNull(iterator.getNodePointer().get());
    }

    @Test
    public void testGetNodePointerOutOfBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertNull(iterator.getNodePointer().get());
    }

    @Test
    public void testGetNodePointerInBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertEquals(attribute1, iterator.getNodePointer().get());
        iterator.next();
        Assert.assertEquals(attribute2, iterator.getNodePointer().get());
    }

    @Test
    public void testGetPositionWithNullAttributes(){
        parent.setNode(null);
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertEquals(0, iterator.getPosition());
    }

    @Test
    public void testGetPositionOutOfBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        Assert.assertEquals(0, iterator.getPosition());
    }

    @Test
    public void testGetPositionInBounds(){
        iterator = new JDOMAttributeIterator(parent, name);
        iterator.next();
        Assert.assertEquals(1, iterator.getPosition());
    }
}
