        when(mockIterator.hasNext()).thenReturn(false);
        Assert.assertFalse(valueIterator.hasNext());
    }

    @Test
    public void testHasNext_whenCalledOnNonEmptyIterator_returnsTrue() {
        when(mockIterator.hasNext()).thenReturn(true);
        Assert.assertTrue(valueIterator.hasNext());
    }

    @Test
    public void testNext_whenCalledOnEmptyIterator_throwsNoSuchElementException() {
        when(mockIterator.hasNext()).thenReturn(false);
        Assert.assertThrows(NoSuchElementException.class, valueIterator::next);
    }

    @Test
    public void testNext_whenCalledOnNonEmptyIterator_returnsCorrectValue() {
        Object mockValue = new Object();
        when(mockIterator.hasNext()).thenReturn(true).thenReturn(false);
        when(mockIterator.next()).thenReturn(mockValue);
        Assert.assertEquals(mockValue, valueIterator.next());
    }

    @Test
    public void testRemove_throwsUnsupportedOperationException() {
        Assert.assertThrows(UnsupportedOperationException.class, valueIterator::remove);
    }
}
